/bin/bash -lc "python -B - <<'PY'
import json,pathlib,hashlib,os
r=pathlib.Path('docs/experiments/r6-robustness-auto');s=json.loads((r/'batch/state.json').read_text());b=s['budget'];tot={}; dev=0
for x in b['reservations']:
 for k,v in x['resources'].items():tot[k]=tot.get(k,0)+v
 if x['purpose'] not in ['final','confirmation']:dev+=x['resources'].get('output_actual_plus_unreleased_reservations_bytes',0)
print('reservations',tot,'nonfinal_bytes',dev)
for k,e in s['events'].items():
 if 'controller' in e.get('identity',{}).get('role',''):print('EVENT',k,json.dumps(e)[:17000])
t=json.loads(pathlib.Path('coordination/research/state/RESEARCH_STATE.json').read_text());print('store',t['version'],t['paused']);print('R6 jobs',[k for k,v in t['jobs'].items() if 'R6-' in str(v.get('spec',{}).get('id',''))]);
for c in ['R6-PROTOCOL-CAPACITY-FREEZE-01','R6-EXECUTION-COMPATIBILITY-02','R6-FIRST-BASELINE-ENTRY-01']: print(c,t['evidence'].get(c))
for p in [r/'STOP',pathlib.Path('STOP'),pathlib.Path('coordination/STOP'),pathlib.Path('coordination/commander/STOP'),pathlib.Path('coordination/executor/STOP')]:print('STOP',p,p.exists())
p=r/'batch/snapshots/4cd9a0dfd5957c2b6521621fe928ef48bc640374b63018e86796c4f1cb96a246/execution-inventory.json';d=json.loads(p.read_text());print('inventory structure',type(d),str(d)[:1200])
PY"

