"""Bounded local startup wait for an externally paused, idle root thread.

This runs in the ordinary controller process under its existing writer lock.
It neither pauses the Goal nor starts a model while awaiting handoff.
"""
import os
import time
from rlflow.jobs import identity
from tools.r6_recovery import RecoveryError
from tools import r6_platform_rpc as rpc,r6_platform_wait as platform
from tools.r6_profile_preparation import guard

PENDING={'PLATFORM_RPC_GOAL_AUTO_CONTINUATION_NOT_STOPPED','PLATFORM_RPC_ROOT_NOT_IDLE',
    'PLATFORM_WAIT_ROOT_TURN_ACTIVE_NO_DISPATCH','PLATFORM_WAIT_HANDOFF_NOT_SETTLED'}


def wait(journal,controller_key,*,timeout_seconds=600,poll_seconds=15):
    guard(journal)
    if type(timeout_seconds) is not int or not 1<=timeout_seconds<=600 or not 0<poll_seconds<=60:
        raise RecoveryError('PLATFORM_HANDOFF_BOUND')
    state=journal.read();owner=state['events'][controller_key];process=identity(os.getpid())
    if (owner['identity']['role']!='r6-controller' or owner.get('controller_process')!=process
            or owner['cursor']['phase']!='FIRST_JOB' or owner['cursor']['completed_jobs']):
        raise RecoveryError('PLATFORM_HANDOFF_FIRST_CONTROLLER_REQUIRED')
    if not rpc.enabled(state):raise RecoveryError('PLATFORM_HANDOFF_RPC_REQUIRED')
    previous=owner.get('platform_handoff_gate')
    if previous:
        deadline=previous['deadline_unix']
        if previous['timeout_seconds']!=timeout_seconds:raise RecoveryError('PLATFORM_HANDOFF_BOUND_DRIFT')
    else:
        deadline=time.time()+timeout_seconds
        owner['platform_handoff_gate']=dict(started_at=time.time(),deadline_unix=deadline,
            timeout_seconds=timeout_seconds,checks=0,status='WAITING',initial_process=process)
        journal.save(state)
    if deadline-time.time()>timeout_seconds:raise RecoveryError('PLATFORM_HANDOFF_CLOCK_BACKWARDS')
    monotonic_deadline=time.monotonic()+max(0,deadline-time.time())
    while True:
        guard(journal)
        if time.time()>=deadline or time.monotonic()>=monotonic_deadline:
            state=journal.read();state['events'][controller_key]['platform_handoff_gate'].update(status='TIMED_OUT',finished_at=time.time())
            state['events'][controller_key]['status']='PLATFORM_HANDOFF_TIMED_OUT'
            journal.save(state);raise RecoveryError('PLATFORM_HANDOFF_TIMED_OUT')
        record=None;pending=None
        try:
            record=rpc.observe(journal.read());rpc.idle(journal.read(),record)
            record=platform.preflight(journal)
        except RecoveryError as error:
            if str(error) not in PENDING:raise
            pending=str(error)
        guard(journal);state=journal.read();owner=state['events'][controller_key];value=owner['platform_handoff_gate']
        value.update(checks=value['checks']+1,last_checked_at=time.time(),process=process,last_rpc=record,
            pending_reason=pending,status='WAITING' if pending else 'READY')
        owner['status']='WAIT_PLATFORM_HANDOFF' if pending else 'PLATFORM_HANDOFF_READY'
        if not pending:
            if time.time()>=deadline or time.monotonic()>=monotonic_deadline:
                value['status']='TIMED_OUT';owner['status']='PLATFORM_HANDOFF_TIMED_OUT';journal.save(state);raise RecoveryError('PLATFORM_HANDOFF_TIMED_OUT')
            value['finished_at']=time.time();journal.save(state);return value
        journal.save(state)
        time.sleep(min(poll_seconds,max(0,min(deadline-time.time(),monotonic_deadline-time.monotonic()))))
"""CPU-only R6 budget checks. Caller holds the single controller writer lock.

No Store permission, submission, settlement or budget refund occurs here.
Reservations remain charged even when an attempt or worker fails.
"""
import copy
import math


class BudgetError(ValueError):
    pass


def amount(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise BudgetError('Resource amount must be numeric')
    if not math.isfinite(value) or value < 0:
        raise BudgetError('Resource amount must be finite and nonnegative')
    return value


def charged(reservation, caps):
    """Conservative charge: max(reserved, every pinned observation), never sum twice."""
    result = {}
    for resources in [reservation['resources'], *[o['resources'] for o in reservation.get('observations', [])]]:
        for resource, value in resources.items():
            if resource not in caps:
                raise BudgetError('Unknown resource: ' + resource)
            result[resource] = max(result.get(resource, 0), amount(value))
    return result


def totals(ledger, *, enforce_caps=True):
    caps = ledger['caps']
    result = {k: amount(ledger['used'][k]) for k in caps}
    seen = set()
    for reservation in ledger['reservations']:
        key = reservation['event_key']
        if key in seen:
            raise BudgetError('Duplicate reservation event')
        seen.add(key)
        for resource, value in charged(reservation, caps).items():
            result[resource] += value
    for resource, value in result.items():
        if enforce_caps and value > amount(caps[resource]):
            raise BudgetError('Cap exceeded: ' + resource)
    return result


def admissible(ledger):
    """Current hard and protected limits; also required before a first dispatch."""
    usage = totals(ledger)
    for resource, protected in ledger['protected_confirmation_delivery_repair'].items():
        # Protected use cannot accidentally become available to exploration.
        dev_used = amount(ledger['used'][resource])
        dev_used += sum(charged(r, ledger['caps']).get(resource, 0) for r in ledger['reservations']
                        if r['purpose'] == 'development')
        if dev_used > ledger['caps'][resource] - amount(protected):
            raise BudgetError('Protected capacity: ' + resource)
    model_cap = ledger['caps']['automatic_model_sessions']
    other_models = amount(ledger['used']['automatic_model_sessions']) + sum(charged(r, ledger['caps']).get('automatic_model_sessions', 0)
                       for r in ledger['reservations']
                       if r['purpose'] not in {'repair', 'final_review'})
    if other_models > model_cap - sum(ledger['protected_model_sessions'].values()):
        raise BudgetError('Protected review/repair sessions')
    for protected_role, count in ledger['protected_model_sessions'].items():
        outside_role = amount(ledger['used']['automatic_model_sessions'])
        outside_role += sum(charged(r, ledger['caps']).get('automatic_model_sessions', 0)
                            for r in ledger['reservations']
                            if r['purpose'] != protected_role)
        if outside_role > model_cap - count:
            raise BudgetError('Protected model role: ' + protected_role)
    return usage


def reserve(ledger, *, event_key, resources, purpose, free_disk_bytes):
    """Return a new ledger; identical replays don't spend again, drift fails.

    event_key binds goal, event, job, input hash and role. Final/recovery use
    of protected capacity is explicit. Ordinary development cannot borrow it.
    Disk check subtracts all outstanding output reservations conservatively.
    """
    required = {'goal_id', 'event_id', 'job_id', 'input_sha256', 'role'}
    if set(event_key) != required or event_key['goal_id'] != ledger['goal_id']:
        raise BudgetError('Incomplete event identity')
    if not all(isinstance(v, str) and v for v in event_key.values()):
        raise BudgetError('Empty event identity')
    digest = event_key['input_sha256']
    if len(digest) != 64 or any(c not in '0123456789abcdef' for c in digest):
